  Folder: "Folder", FolderTree: "Sitemap4", Ghost: "Ufo", Globe: "Earth", Home: "House5", IceCreamBowl: "HotDrink", Inbox: "InboxArrowDown",
  Keyboard: "Keyboard", Laptop: "Laptop", Layers3: "Layers3", Link2: "Link", ListFilter: "Filter",
  Mail: "Envelope", MailOpen: "EnvelopeOpen", Pin: "Target", PinFilled: "Target", MapPin: "Location2", MessageCircle: "MsgSmile",
  MessageSquare: "MsgWriting", MessageSquareText: "MsgWriting", MessagesSquare: "Msgs", Mic: "Microphone", Monitor: "Computer", Moon: "DarkLight",
  Network: "Nodes", NotebookPen: "PenWriting4", Paperclip: "Paperclip", PenLine: "Pencil", Pencil: "Pencil", Plus: "AddCircle", Reply: "MsgWriting",
  ReplyAll: "Msgs", Rocket: "Rocket", ScanLine: "FacialRecognition", Search: "Magnifier", SearchOutline: "Magnifier", Send: "PaperPlane2",
  Server: "Computer", Settings: "Gear2", Settings2: "Sliders", ShieldAlert: "TriangleWarning", ShieldCheck: "ShieldCheck", Sparkle: "Sparkle3",
